import{_ as e,o as i,c as a,a4 as r}from"./chunks/framework.RZAa07QS.js";const u=JSON.parse('{"title":"Sprint 11 — Approval Workflow & Full Publishing","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprints/Sprint_11_Approval_Workflow_Publishing.md","filePath":"plan/sprints/Sprint_11_Approval_Workflow_Publishing.md"}'),l={name:"plan/sprints/Sprint_11_Approval_Workflow_Publishing.md"};function s(d,t,n,o,p,c){return i(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="sprint-11-—-approval-workflow-full-publishing" tabindex="-1">Sprint 11 — Approval Workflow &amp; Full Publishing <a class="header-anchor" href="#sprint-11-—-approval-workflow-full-publishing" aria-label="Permalink to &quot;Sprint 11 — Approval Workflow &amp; Full Publishing&quot;">​</a></h1><p><strong>Timeline:</strong> Weeks 21–22 (Oct 7–20, 2026) <strong>Jira:</strong> DA Sprint 11 <strong>Phase:</strong> Phase 5 — Content Workflow &amp; Publishing <strong>Goal:</strong> Implement the multi-step approval workflow (Creator → Account Manager → Brand Client) and the full publishing pipeline (APPROVED post → RabbitMQ → publisher-service → social platform).</p><p>&gt; <strong>AI Parallel:</strong> AI Iteration 4 runs concurrently this sprint.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Title</th><th>Owner</th></tr></thead><tbody><tr><td>E31</td><td>Approval Workflow</td><td>Trung</td></tr><tr><td>E32</td><td>Publishing System</td><td>Trung, Phước</td></tr><tr><td>E33</td><td>Publish Error Handling</td><td>Phước, Trung</td></tr></tbody></table><p><strong>Deliverables by end of Sprint 11:</strong></p><ul><li>Full approval chain working: CONTENT_CREATOR submits → ACCOUNT_MANAGER reviews → BRAND_CLIENT approves → SCHEDULED</li><li>Approved post enqueued to RabbitMQ for publishing</li><li>All 5 platform adapters tested with real sandbox accounts</li><li>Retry + DLQ + failure notification working end-to-end</li></ul><hr><h2 id="epic-e31-—-approval-workflow" tabindex="-1">EPIC E31 — Approval Workflow <a class="header-anchor" href="#epic-e31-—-approval-workflow" aria-label="Permalink to &quot;EPIC E31 — Approval Workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E31-01</td><td>Implement POST /api/v1/posts/{id}/submit (CONTENT_CREATOR submits → PENDING_REVIEW)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E31-02</td><td>Implement POST /api/v1/posts/{id}/account-review (ACCOUNT_MANAGER approves or rejects + note)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E31-03</td><td>Implement POST /api/v1/posts/{id}/client-approve (BRAND_CLIENT approves → SCHEDULED)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E31-04</td><td>Implement POST /api/v1/posts/{id}/client-reject (BRAND_CLIENT rejects + feedback)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>Full status machine:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DRAFT → (submit) → PENDING_REVIEW</span></span>
<span class="line"><span>PENDING_REVIEW → (account-review: approve) → SENT_TO_CLIENT</span></span>
<span class="line"><span>PENDING_REVIEW → (account-review: reject) → DRAFT (with rejectionNote)</span></span>
<span class="line"><span>SENT_TO_CLIENT → (client-approve) → SCHEDULED</span></span>
<span class="line"><span>SENT_TO_CLIENT → (client-reject) → DRAFT (with clientFeedback)</span></span>
<span class="line"><span>SCHEDULED → (scheduled time reached) → PUBLISHING</span></span>
<span class="line"><span>PUBLISHING → (publisher callback: success) → PUBLISHED</span></span>
<span class="line"><span>PUBLISHING → (publisher callback: failure x3) → FAILED</span></span></code></pre></div><p><strong>Notes:</strong></p><ul><li>On SCHEDULED: trigger enqueue to RabbitMQ for the scheduled time.</li><li>If scheduledAt is in the past (immediate publish): enqueue immediately.</li><li>Notifications on each transition: notify the next actor in the chain.</li></ul><hr><h2 id="epic-e32-—-publishing-system" tabindex="-1">EPIC E32 — Publishing System <a class="header-anchor" href="#epic-e32-—-publishing-system" aria-label="Permalink to &quot;EPIC E32 — Publishing System&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E32-01</td><td>Implement Smart Ingestion (package post + encrypted token + platform configs into a RabbitMQ message)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E32-02</td><td>Implement RabbitMQ consumer in publisher-service (FIFO, exactly-once, acknowledgement)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E32-03</td><td>Implement Facebook adapter (Graph API: IMAGE post and REEL/VIDEO)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E32-04</td><td>Implement Instagram adapter (2-step: create container → publish)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E32-05</td><td>Implement TikTok adapter (Direct Post for video ≤60s, Creator Upload for video &gt;60s)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E32-06</td><td>Implement Threads adapter (2-step: create container → publish, max 500 chars)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E32-07</td><td>Implement Zalo OA adapter</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E32-08</td><td>Implement HTTP callback → business-service after publish completes (update post status: PUBLISHED/FAILED)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>Smart Ingestion (DA-E32-01):</strong></p><ul><li>Triggered when post transitions to SCHEDULED</li><li>For each targetPlatform: fetch encrypted social token from <code>social_accounts</code></li><li>Build PublishJobMessage per platform (one message per platform)</li><li>Set RabbitMQ message <code>scheduledDeliveryTime</code> if scheduledAt is future</li><li>Use delayed message plugin (<code>rabbitmq_delayed_message_exchange</code>) for scheduled delivery</li></ul><p><strong>Exactly-once (DA-E32-02):</strong></p><ul><li>Use RabbitMQ manual acknowledgement (<code>basicAck</code> only after successful publish or DLQ)</li><li>Store <code>processingPostIds</code> in Redis to prevent duplicate processing if consumer crashes mid-flight</li></ul><hr><h2 id="epic-e33-—-publish-error-handling" tabindex="-1">EPIC E33 — Publish Error Handling <a class="header-anchor" href="#epic-e33-—-publish-error-handling" aria-label="Permalink to &quot;EPIC E33 — Publish Error Handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E33-01</td><td>Implement retry logic (up to 3 attempts, exponential backoff: 30s, 60s, 120s)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E33-02</td><td>Implement Dead Letter Queue handler (Admin can view and manually retry or discard failed posts)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E33-03</td><td>Implement failure notification (send alert to Account Manager when a post fails after all retries)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>DLQ handler (DA-E33-02):</strong></p><ul><li>Admin API: <code>GET /api/v1/admin/dlq</code> — list failed messages</li><li>Admin API: <code>POST /api/v1/admin/dlq/{messageId}/retry</code> — re-enqueue</li><li>Admin API: <code>DELETE /api/v1/admin/dlq/{messageId}</code> — discard</li></ul><p><strong>Notes:</strong></p><ul><li>E32 adapters in this sprint are the PRODUCTION-QUALITY implementations (replacing the Sprint 8 scaffolding).</li><li>E32-03 to E32-07: test each adapter against a real sandbox developer account before marking done.</li></ul><hr><h2 id="sprint-11-checklist" tabindex="-1">Sprint 11 Checklist <a class="header-anchor" href="#sprint-11-checklist" aria-label="Permalink to &quot;Sprint 11 Checklist&quot;">​</a></h2><ul><li>[ ] CONTENT_CREATOR submits post → status = PENDING_REVIEW, ACCOUNT_MANAGER notified</li><li>[ ] ACCOUNT_MANAGER approves → status = SENT_TO_CLIENT, BRAND_CLIENT notified</li><li>[ ] ACCOUNT_MANAGER rejects → status = DRAFT, rejection note saved</li><li>[ ] BRAND_CLIENT approves → status = SCHEDULED, post enqueued</li><li>[ ] BRAND_CLIENT rejects → status = DRAFT, client feedback saved</li><li>[ ] Scheduled post: enqueued with delayed delivery time</li><li>[ ] Immediate post: enqueued and published within 30 seconds</li><li>[ ] Facebook IMAGE post published to sandbox Fanpage</li><li>[ ] Instagram PHOTO post published (2-step container)</li><li>[ ] TikTok video published (Direct Post ≤60s)</li><li>[ ] Threads text post published</li><li>[ ] Zalo OA article published</li><li>[ ] Failed publish: retried 3x with 30s/60s/120s delays</li><li>[ ] After all retries: message in DLQ, Account Manager notified</li><li>[ ] Admin can view DLQ, retry, or discard messages</li></ul>`,32)])])}const b=e(l,[["render",s]]);export{u as __pageData,b as default};
